// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC721V2 {
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

/**
 * CryptoGangs StakeBurn V2
 *
 * CryptoGangs uses Limit Break's transfer validator. The NFT owner must be the
 * caller when depositing, so the web app calls CryptoGangs.safeTransferFrom
 * directly for each selected token. This receiver records the requested action
 * from the transfer data; it never needs collection-wide approval.
 */
contract CryptoGangsStakeBurnV2 {
    IERC721V2 public constant NFT = IERC721V2(0x361E3C0cdC8888BE48CDe2821Ba4173582593Fd9);
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    uint8 private constant ACTION_STAKE = 1;
    uint8 private constant ACTION_BURN = 2;

    struct Position {
        address owner;
        uint64 lockedAt;
        uint64 unlockAt;
    }

    address public owner;
    uint256 private locked;
    mapping(uint256 => Position) public positions;
    mapping(address => uint256) public currentStaked;
    mapping(address => uint256) public lifetimeBurned;

    event Staked(address indexed wallet, uint256 indexed tokenId, uint64 unlockAt);
    event Unstaked(address indexed wallet, uint256 indexed tokenId);
    event Burned(address indexed wallet, uint256 indexed tokenId);
    event OwnerWithdrawal(address indexed wallet, uint256 indexed tokenId);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error InvalidNFT();
    error InvalidSender();
    error InvalidAction();
    error InvalidLockPeriod();
    error TokenNotStaked();
    error NotTokenOwner();
    error StillLocked(uint64 unlockAt);
    error OnlyOwner();
    error ZeroAddress();
    error Reentrancy();

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    modifier nonReentrant() {
        if (locked == 1) revert Reentrancy();
        locked = 1;
        _;
        locked = 0;
    }

    constructor() {
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function onERC721Received(address, address from, uint256 tokenId, bytes calldata data)
        external
        nonReentrant
        returns (bytes4)
    {
        if (msg.sender != address(NFT)) revert InvalidNFT();
        if (from == address(0)) revert InvalidSender();

        (uint8 action, uint64 durationDays) = abi.decode(data, (uint8, uint64));

        if (action == ACTION_STAKE) {
            if (!_validDuration(durationDays)) revert InvalidLockPeriod();
            uint64 lockedAt = uint64(block.timestamp);
            uint64 unlockAt = lockedAt + durationDays * uint64(1 days);
            positions[tokenId] = Position({owner: from, lockedAt: lockedAt, unlockAt: unlockAt});
            currentStaked[from] += 1;
            emit Staked(from, tokenId, unlockAt);
        } else if (action == ACTION_BURN) {
            if (durationDays != 0) revert InvalidLockPeriod();
            lifetimeBurned[from] += 1;
            NFT.safeTransferFrom(address(this), DEAD, tokenId);
            emit Burned(from, tokenId);
        } else {
            revert InvalidAction();
        }

        return this.onERC721Received.selector;
    }

    function unstake(uint256 tokenId) external nonReentrant {
        Position memory position = positions[tokenId];
        if (position.owner == address(0)) revert TokenNotStaked();
        if (position.owner != msg.sender) revert NotTokenOwner();
        if (block.timestamp < position.unlockAt) revert StillLocked(position.unlockAt);

        delete positions[tokenId];
        currentStaked[msg.sender] -= 1;
        NFT.safeTransferFrom(address(this), msg.sender, tokenId);
        emit Unstaked(msg.sender, tokenId);
    }

    function ownerWithdraw(uint256 tokenId) external onlyOwner nonReentrant {
        Position memory position = positions[tokenId];
        if (position.owner != address(0)) {
            delete positions[tokenId];
            currentStaked[position.owner] -= 1;
        }
        NFT.safeTransferFrom(address(this), msg.sender, tokenId);
        emit OwnerWithdrawal(msg.sender, tokenId);
    }

    function scoreOf(address wallet) external view returns (uint256) {
        return currentStaked[wallet] + lifetimeBurned[wallet];
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function _validDuration(uint64 durationDays) private pure returns (bool) {
        return durationDays == 7 || durationDays == 30 || durationDays == 90 || durationDays == 180
            || durationDays == 365;
    }
}
